import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"迁移","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/migration.md","filePath":"zh-Hans/deep-dive/migration.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/migration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="迁移" tabindex="-1">迁移 <a class="header-anchor" href="#迁移" aria-label="Permalink to “迁移”">​</a></h1><p>&quot;迁移&quot;一词在这里代表两件不相关的事。</p><p><strong>远程迁移</strong>是面向用户的操作：手动转换远端存储布局以满足某个功能的要求，例如开启加密或<a href="./asymmetric-storage">非对称存储</a>。Sync Engine 从不自动执行它，因为同步策略因设备而异，应用到一半的远端是灾难性的。它记录在<a href="./../usage/remote-migration">远程迁移指南</a>中。</p><p><strong>迁移</strong>（本页和代码库中的含义）指自动升级 Sync Engine 自己以旧格式持久化的数据，例如 <code>data.json</code> 中的设置和 IndexedDB store。它从不触碰远端，也从来不是用户触发的操作。</p><p><strong>对用户：在窗口期内至少打开一次 Obsidian / 更新一次 Sync Engine，即可完成自动迁移。需要人工操作的部分，请确保在截止日期之前完成。</strong></p><p>出于实现简单性的考虑，迁移是即席的、有期限的：</p><ul><li>只写修复某个特定旧数据形态所需的最少代码。每个迁移都是一个普通函数，在加载时运行，不再需要时自我删除。</li><li>通过数据形态识别旧数据。迁移一旦运行过，再次运行必须是无操作。</li><li>在数据可见、且尚无消费者读取的最早缝隙处运行。</li><li>通过 <code>saveSettings</code> 持久化结果。</li><li>每个迁移都带一条 <code>// TODO: remove after &lt;date&gt;</code> 注释，标明删除这段即席代码的截止日期。</li></ul><h2 id="进行中的迁移" tabindex="-1">进行中的迁移 <a class="header-anchor" href="#进行中的迁移" aria-label="Permalink to “进行中的迁移”">​</a></h2><h3 id="加密主盐" tabindex="-1">加密主盐 <a class="header-anchor" href="#加密主盐" aria-label="Permalink to “加密主盐”">​</a></h3><ul><li>原因：主盐从 Fs UID 派生，而 URL 规范化会改变 UID。没有变通方案的话，每个已用加密上传的文件都将无法解密。</li><li>窗口：2026-10-17 至 2027-04-17</li><li>范围：启用了加密、且 S3/WebDAV 端点被 URL 规范化改变的用户（端点中包含一个或多个编码形式与字面形式不同的字符）。</li><li>操作：迁移前的端点被记录为 <code>legacyEndpoint</code>，主盐继续从旧的 Fs UID 派生。窗口结束后这个变通方案会被移除。</li><li>人工操作：受影响的用户需要在窗口结束前按照<a href="./../usage/remote-migration">远程迁移指南</a>重新上传加密的远端，因为变通方案移除后盐会变回去。</li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};